// Ported from the Node app's Sequelize model Mark (first generated by tools/gen-efcore.mjs).
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using SchoolERP.Domain.Entities;

namespace SchoolERP.Infrastructure.Persistence.Configurations;

internal sealed class MarkConfiguration : IEntityTypeConfiguration<Mark>
{
    public void Configure(EntityTypeBuilder<Mark> builder)
    {
        builder.ToTable("marks");
        builder.ConfigureAudit();
        builder.HasQueryFilter(e => !e.Delstatus);
        builder.HasKey(e => e.Id);
        builder.Property(e => e.Id).HasColumnName("id").UseIdentityColumn();
        builder.Property(e => e.ExamId).HasColumnName("exam_id");
        builder.Property(e => e.StudentId).HasColumnName("student_id");
        builder.Property(e => e.SubjectId).HasColumnName("subject_id");
        builder.Property(e => e.Marks).HasColumnName("marks").HasColumnType("decimal(6,2)");
        builder.Property(e => e.PracticalMarks).HasColumnName("practical_marks").HasColumnType("decimal(6,2)");
        builder.HasIndex(e => new { e.ExamId, e.StudentId, e.SubjectId }).IsUnique().HasDatabaseName("uq_mark");
        builder.HasOne(e => e.Exam).WithMany(p => p.Marks).HasForeignKey(e => e.ExamId).OnDelete(DeleteBehavior.NoAction);
        builder.HasOne(e => e.Student).WithMany(p => p.Marks).HasForeignKey(e => e.StudentId).OnDelete(DeleteBehavior.NoAction);
        builder.HasOne(e => e.Subject).WithMany(p => p.Marks).HasForeignKey(e => e.SubjectId).OnDelete(DeleteBehavior.NoAction);
    }
}
